#!/usr/bin/env node
/**
 * Google-Schaufenster: hält die Zahl der Artikel auf dem Kanal «Google & YouTube» unter der Quote des Merchant Centers
 * (Standard 150 000 Artikel je Bereich; ein Artikel ist eine Variante). Begründung, Regel und Zahlen: automation/lib/gmc_schaufenster.mjs.
 *
 * PHASEN (PHASE=…, Vorgabe plan)
 *   plan          NUR LESEN: liest alle aktiven Produkte (Bulk), rechnet das Schaufenster, nennt Zahlen, Gründe und Beispiele
 *                 auf BEIDEN Seiten (bleibt / geht) und schreibt den Plan nach PLAN_AUS.
 *   abwaehlen     LIVE=1: nimmt Produkte, die nicht ins Schaufenster passen, vom Kanal (publishableUnpublish, 10 je Anfrage). Bestellte und gut bewertete
 *                 Produkte (Stufe 0) bleiben; sind die Bestellungen nicht vollständig lesbar, bricht der Lauf ab.
 *   aufnehmen     LIVE=1: stellt Produkte zurück, die dieses Werkzeug früher abgewählt hat UND die wieder ins Schaufenster passen.
 *   zuruecksetzen LIVE=1: VOLLE Rücknahme: stellt alles zurück, was dieses Werkzeug abgewählt hat (ausser Sperrtag), auch Produkte mit
 *                 Ausschlussfeld oder ausserhalb des Budgets. Danach wählt ein neuer Lauf wieder ab; zum Stoppen die Freigabedatei löschen.
 *   pruefen       NUR LESEN: liest frisch und vergleicht mit Manifest und Plan, nennt die Varianten auf Google.
 *
 * SICHERHEIT
 *   - Scharf nur mit LIVE=1 UND der Freigabedatei dropship/GMC-SCHAUFENSTER-FREI.txt (löschen = Stopp, auch mitten im Lauf: sie wird vor jedem
 *     Stück neu geprüft, Exit 4; ein Lauf auf GitHub Actions sieht nur seine Kopie, dort stoppt «Run abbrechen»); KATALOG (fertige Datei) nie mit LIVE=1.
 *   - Ein Plan mit Fehlern (zu wenige Zeilen, leeres oder zu grosses Schaufenster, zu viele unklare Zeilen, über 70 % abzuwählen, über 5 %
 *     ohne Google-Kategorie) schreibt nichts (Exit 2). BUDGET unter 40 000 wird nie angenommen.
 *   - Manifest (dropship/gmc_schaufenster_manifest.jsonl): eine Zeile je Produkt VOR dem Aufruf («ab-versucht»: Teilfehler oder Absturz
 *     verlieren nichts), «auf» nach belegter Rücknahme. Der Manifest-Pfad wird vor dem ersten Aufruf auf Schreibbarkeit geprüft.
 *   - Es kommt nie ein Produkt hinzu, das nicht schon auf Google lag (Sperrtag, Policy) und nie eines ohne Manifest-Eintrag zurück.
 *   - Produkte, die dreimal fehlschlugen (dropship/gmc_schaufenster_fehler.txt), werden übersprungen und genannt.
 *   - Drosselung wird nie umgangen: bleibt sie bestehen, endet der Lauf (Exit 4), der nächste macht idempotent weiter.
 *
 * ENV  SHOPIFY_CLIENT_ID + SHOPIFY_CLIENT_SECRET (+ SHOPIFY_SHOP)  ·  LIVE=1  ·  PHASE  ·  MAX (Vorgabe 2000, «alle»)  ·  ONLY=handle,handle (Stichprobe)
 *      BUDGET (Varianten, Vorgabe 90000, mindestens 40000)  ·  PLAN_AUS (Vorgabe /tmp/gmc_schaufenster_plan.json)  ·  MANIFEST  ·  FREIGABE  ·  FEHLERDATEI
 *      KATALOG (fertige Bulk-Datei statt Lesen, nur ohne LIVE)
 * Exit  0 ok · 1 Zugang/Einstellung · 2 Plan nicht erlaubt · 3 Fehlschläge oder Defekt (abgewählt, aber noch auf Google) · 4 Drosselung/Abbruch
 *       5 pruefen: Google trägt noch Produkte ausserhalb des Schaufensters
 */
import { randomUUID } from 'node:crypto';
import { appendFileSync, existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname } from 'node:path';
import { fileURLToPath } from 'node:url';
import { normalizeShopifyHost } from './lib/shopify_host.mjs';
import { shopifyClientSecret } from './lib/shopify_secret.mjs';
import { shopifyGql } from './lib/shopify_gql.mjs';
import {
  GOOGLE_PUBLICATION, BUDGET_VARIANTEN, MIN_BUDGET, plan, stuecke, mutation, auswerten, parseManifest, manifestZeile, ratingAus, bestellteIds, bewaehrt,
} from './lib/gmc_schaufenster.mjs';

const ERWARTETER_SHOP = 'au3j0y-hq.myshopify.com';
let SHOP;
try {
  SHOP = normalizeShopifyHost(process.env.SHOPIFY_SHOP ?? ERWARTETER_SHOP);
  if (SHOP !== ERWARTETER_SHOP) throw new Error('fremder Shop');
} catch {
  console.log('ABBRUCH: SHOPIFY_SHOP muss der bestätigte LuxeStyle-Shop sein.');
  process.exit(1);
}
const API = '2026-01';   // 2025-01 ist abgelaufen: Shopify antwortete still mit 2026-01 (Prüfer 28.10.)
const LIVE = process.env.LIVE === '1';
const PHASE = (process.env.PHASE || 'plan').trim();
const BUDGET = Number(process.env.BUDGET || BUDGET_VARIANTEN);
const MAX = /^alle$/i.test(process.env.MAX || '') ? Infinity : Number(process.env.MAX || 2000);
const ONLY = (process.env.ONLY || '').split(',').map(s => s.trim()).filter(Boolean);
const PLAN_AUS = process.env.PLAN_AUS || '/tmp/gmc_schaufenster_plan.json';
const HIER = p => fileURLToPath(new URL(p, import.meta.url));
const MANIFEST = process.env.MANIFEST || HIER('../dropship/gmc_schaufenster_manifest.jsonl');
const FREIGABE = process.env.FREIGABE || HIER('../dropship/GMC-SCHAUFENSTER-FREI.txt');
const FEHLERDATEI = process.env.FEHLERDATEI || HIER('../dropship/gmc_schaufenster_fehler.txt');
const STUECK = 10;
const SCHREIBT = ['abwaehlen', 'aufnehmen', 'zuruecksetzen'];
const schlaf = ms => new Promise(r => setTimeout(r, ms));
const heute = () => new Date().toISOString().slice(0, 10);

if (![...SCHREIBT, 'plan', 'pruefen'].includes(PHASE)) { console.log(`ABBRUCH: unbekannte PHASE «${PHASE}»`); process.exit(1); }
if (!Number.isFinite(BUDGET) || BUDGET < MIN_BUDGET) { console.log(`ABBRUCH: BUDGET muss eine Zahl >= ${MIN_BUDGET} sein (ein Tippfehler würde fast alles abwählen)`); process.exit(1); }
if (!(MAX >= 1)) { console.log('ABBRUCH: MAX muss >= 1 oder «alle» sein'); process.exit(1); }
if (SCHREIBT.includes(PHASE) && !LIVE) console.log('TROCKENLAUF (LIVE=1 schreibt).');
if (LIVE && process.env.KATALOG) { console.log('ABBRUCH: KATALOG (fertige Datei) gilt nur im Trockenlauf; scharf wird frisch gelesen.'); process.exit(1); }
if (LIVE && SCHREIBT.includes(PHASE) && !existsSync(FREIGABE)) {
  console.log('ABBRUCH: dropship/GMC-SCHAUFENSTER-FREI.txt fehlt (Freigabe des Besitzers oder Stopp).'); process.exit(1);
}

async function holeToken() {
  const id = process.env.SHOPIFY_CLIENT_ID, sec = shopifyClientSecret(process.env.SHOPIFY_CLIENT_SECRET);
  if (!id || !sec) { console.log('ABBRUCH: SHOPIFY_CLIENT_ID oder _SECRET fehlt.'); return null; }
  let r;
  try {
    r = await fetch(`https://${SHOP}/admin/oauth/access_token`, {
      method: 'POST', redirect: 'error', signal: AbortSignal.timeout(30000), headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ client_id: id, client_secret: sec, grant_type: 'client_credentials' }),
    });
  } catch { console.log('ABBRUCH: Token-Anfrage fehlgeschlagen.'); return null; }
  if (!r.ok) { console.log(`ABBRUCH: Token HTTP ${r.status}`); return null; }
  let j;
  try { j = await r.json(); } catch { console.log('ABBRUCH: Token-Antwort nicht lesbar.'); return null; }
  if (typeof j?.access_token !== 'string' || !j.access_token) { console.log('ABBRUCH: Token fehlt in der Antwort.'); return null; }
  return j.access_token;
}
const TOKEN = await holeToken();
if (!TOKEN) process.exit(1);
const q = (a, b) => shopifyGql(SHOP, API, TOKEN, a, b);

/** Alle aktiven Produkte per Bulk-Abfrage (eine Minute). Die Zeilen sind frisch; ein Lauf ohne Beleg «vollständig» schreibt nichts. */
async function liesProdukte() {
  if (process.env.KATALOG) return zeilen(readFileSync(process.env.KATALOG, 'utf8'), null);
  const lauf = (await q(`{currentBulkOperation(type:QUERY){status}}`)).currentBulkOperation;
  if (lauf && ['CREATED', 'RUNNING', 'CANCELING'].includes(lauf.status)) { console.log('ABBRUCH: Es läuft schon eine Bulk-Abfrage, später wiederholen.'); process.exit(4); }
  const inner = `{ products(query:"status:active") { edges { node { id handle title tags variantsCount{count} gp:publishedOnPublication(publicationId:"${GOOGLE_PUBLICATION}") ex:metafield(namespace:"mm-google-shopping", key:"excluded_destination"){ value } cat:metafield(namespace:"mm-google-shopping", key:"google_product_category"){ value } rt:metafield(namespace:"reviews", key:"rating"){ value } rc:metafield(namespace:"reviews", key:"rating_count"){ value } } } } }`;
  const m = (await q(`mutation($q:String!){bulkOperationRunQuery(query:$q){bulkOperation{id} userErrors{message}}}`, { q: inner })).bulkOperationRunQuery;
  if (m.userErrors?.length) {
    const belegt = m.userErrors.some(e => /already in progress|bereits|in progress/i.test(String(e.message)));
    console.log(`ABBRUCH: Bulk-Abfrage: ${JSON.stringify(m.userErrors)}`); process.exit(belegt ? 4 : 1);
  }
  for (let i = 0; i < 240; i++) {
    await schlaf(10000);
    const s = (await q(`{currentBulkOperation(type:QUERY){status errorCode objectCount url}}`)).currentBulkOperation;
    if (s.status === 'COMPLETED') return zeilen(await (await fetch(s.url)).text(), Number(s.objectCount));
    if (['FAILED', 'CANCELED', 'EXPIRED'].includes(s.status)) { console.log(`ABBRUCH: Bulk ${s.status} ${s.errorCode || ''}`); process.exit(1); }
  }
  console.log('ABBRUCH: Bulk-Abfrage dauert zu lange.'); process.exit(4);
}
function zeilen(text, erwartet) {
  const aus = text.split('\n').filter(Boolean).map(z => {
    const o = JSON.parse(z);
    const b = ratingAus(o.rt?.value, o.rc?.value);
    return { id: o.id, handle: o.handle, titel: o.title || '', tags: o.tags || [], varianten: o.variantsCount?.count, aufGoogle: typeof o.gp === 'boolean' ? o.gp : null,
      ausschluss: o.ex?.value || null, kategorie: o.cat?.value || null, rating: b ? b.rating : null, bewertungen: b ? b.anzahl : null, bestellt: false };
  });
  if (erwartet != null && aus.length !== erwartet) { console.log(`ABBRUCH: ${aus.length} Zeilen gelesen, Shopify meldet ${erwartet}.`); process.exit(1); }
  return aus;
}

/**
 * Produkte aus bezahlten Bestellungen (Stufe 0 «bewährt»). Nur lesen. Ältere Bestellungen als 60 Tage liefert Shopify nur mit dem Recht `read_all_orders`:
 * `ordersCount` gegen die gelesene Zahl ist deshalb die Probe; stimmt sie nicht, gilt die Liste als unvollständig (und ein Schreiblauf bricht ab).
 */
async function liesBestellte() {
  const alle = []; let nach = null, gesamt = null;
  try {
    for (let i = 0; i < 100; i++) {
      const d = await q(`query($c:String){ ordersCount(limit:null){ count } orders(first:100, after:$c, sortKey:CREATED_AT){ pageInfo{ hasNextPage endCursor } nodes{ test cancelledAt displayFinancialStatus lineItems(first:100){ pageInfo{ hasNextPage } nodes{ product{ id } } } } } }`, { c: nach });
      gesamt = d.ordersCount?.count ?? gesamt;
      alle.push(...(d.orders?.nodes || []));
      if (!d.orders?.pageInfo?.hasNextPage) break;
      nach = d.orders.pageInfo.endCursor;
    }
  } catch (e) { return { ids: new Set(), vollstaendig: false, gelesen: alle.length, gesamt, fehler: String(e.message).slice(0, 160) }; }
  const b = bestellteIds(alle);
  // Fehlt ordersCount, ist die Vollständigkeit unbelegt: dann gilt die Liste als unvollständig (fail-closed; GEMESSEN 28.10.: Shopify liefert {"count":29,"precision":"EXACT"}).
  const vollstaendig = b.vollstaendig && gesamt != null && gesamt === alle.length;
  const grund = gesamt == null ? 'ordersCount fehlt' : `gelesen ${alle.length} von ${gesamt} Bestellungen${b.vollstaendig ? ' (Recht read_all_orders prüfen)' : ' (Positionen abgeschnitten)'}`;
  return { ids: b.ids, vollstaendig, gelesen: alle.length, gesamt, fehler: vollstaendig ? null : grund };
}

function liesManifest() {
  if (!existsSync(MANIFEST)) return { ids: new Set(), generationen: new Map(), kaputt: 0, veraltet: 0 };
  return parseManifest(readFileSync(MANIFEST, 'utf8'));
}
/** Zeilen anhängen; endet die Datei nicht auf einen Zeilenumbruch, steht vor der ersten neuen Zeile einer (sonst verschmölzen zwei Einträge). */
let umbruchNoetig = false;
function anhaengen(pfad, text) {
  appendFileSync(pfad, (umbruchNoetig ? '\n' : '') + text);
  umbruchNoetig = false;
}
function liesFehler() {
  const n = new Map();
  if (!existsSync(FEHLERDATEI)) return n;
  for (const z of readFileSync(FEHLERDATEI, 'utf8').split('\n')) { const id = z.split('\t')[0]; if (id) n.set(id, (n.get(id) || 0) + 1); }
  return n;
}

function bericht(p, alle) {
  const z = p.zahlen, v = p.varianten;
  console.log(`\nSCHAUFENSTER (Budget ${z.budget} Varianten, Deckel je Kategorie ${z.katDeckel})`);
  console.log(`  gelesen ${alle.length} aktive Produkte · auf Google jetzt ${alle.filter(x => x.aufGoogle === true).length} · unklar ${p.unklar}`);
  console.log(`  zulässig: Stufe 0 (bewährt: bestellt oder gut bewertet) ${z.produkte[0]} · Stufe 1 (Fortura/CH-Lager) ${z.produkte[1]} · Stufe 2 (Marge A/B) ${z.produkte[2]} · Stufe 3 (Rest) ${z.produkte[3]}`);
  console.log(`  im Schaufenster: S0 ${z.drin[0]} / ${z.varianten[0]} Var. · S1 ${z.drin[1]} / ${z.varianten[1]} Var. · S2 ${z.drin[2]} / ${z.varianten[2]} Var. · S3 ${z.drin[3]} / ${z.varianten[3]} Var. · zusammen ${z.varianten.gesamt} Varianten`);
  console.log(`  Varianten auf Google: jetzt ${v.vorher} → nach dem Lauf ${v.nachher}   (Quote 150000, Budget ${z.budget})`);
  console.log(`  ABWÄHLEN ${p.abwaehlen.length} Produkte, Gründe ${JSON.stringify(p.gruende)}`);
  console.log(`  AUFNEHMEN ${p.aufnehmen.length} Produkte (aus dem Manifest, passen wieder) · ZURÜCKSETZEN ${p.zuruecksetzen.length} (alles aus dem Manifest, ausser Sperrtag)`);
  const proKat = {};
  for (const x of alle) if (p.drin.has(x.id) && x.aufGoogle === true) { const k = String(x.kategorie).split(' > ').slice(0, 2).join(' > '); proKat[k] = (proKat[k] || 0) + Number(x.varianten); }
  console.log('  grösste Kategorien im Schaufenster (Varianten): ' + Object.entries(proKat).sort((a, b) => b[1] - a[1]).slice(0, 6).map(([k, n]) => `${k}=${n}`).join(' · '));
  const proben = (liste, n) => liste.filter((_, i) => i % Math.max(1, Math.floor(liste.length / n)) === 0).slice(0, n);
  console.log('  BLEIBEN (Beispiele je Stufe):');
  for (const s of [0, 1, 2, 3]) for (const x of proben(alle.filter(a => p.drin.get(a.id) === s && a.aufGoogle === true), 4)) console.log(`    S${s} ${x.handle} · ${x.varianten} Var.`);
  console.log('  GEHEN (Beispiele, über die Gründe verteilt):');
  const proGrund = {};
  for (const x of p.abwaehlen) (proGrund[x.grund] ||= []).push(x);
  for (const [g, l] of Object.entries(proGrund)) for (const x of proben(l, 3)) console.log(`    ${g} · ${x.handle} · ${x.varianten} Var.`);
  if (p.fehler.length) console.log(`\nPLAN NICHT ERLAUBT: ${p.fehler.join(' | ')}`);
}

const alle = await liesProdukte();
const bestellt = await liesBestellte();
for (const x of alle) x.bestellt = bestellt.ids.has(x.id);
console.log(`BEWÄHRT: ${bestellt.ids.size} Produkte aus bezahlten Bestellungen (${bestellt.gelesen} Bestellungen gelesen${bestellt.gesamt != null ? `, Shopify zählt ${bestellt.gesamt}` : ''}) · dazu ${alle.filter(x => !x.bestellt && bewaehrt(x)).length} mit guter Bewertung`);
if (!bestellt.vollstaendig) console.log(`WARNUNG: Bestellungen unvollständig gelesen (${bestellt.fehler}): bestellte Produkte sind nicht sicher geschützt.`);
/** Bewertungsfelder: GEMESSEN 28.10. tragen 2 076 von 56 618 Produkten eines. Viel weniger heisst: nicht (richtig) gelesen, etwa eine alte KATALOG-Datei ohne reviews.rating. */
const MIN_BEWERTET = 200;
const mitRating = alle.filter(x => x.rating != null).length;
console.log(`BEWERTUNGSFELDER: bei ${mitRating} Produkten gelesen${mitRating < MIN_BEWERTET ? ` (unter ${MIN_BEWERTET}: Stufe 0 gilt dann nur für bestellte Produkte, schwach Bewertete werden nicht erkannt)` : ''}`);
if (ONLY.length) console.log(`ONLY: Stichprobe von ${ONLY.length} Handles (der Plan rechnet trotzdem über alle ${alle.length} Produkte).`);
const man = liesManifest();
if (man.kaputt) console.log(`HINWEIS: ${man.kaputt} kaputte Manifest-Zeilen: Zustand unbekannt, keine Schreibfreigabe.`);
if (man.veraltet) console.log(`HINWEIS: ${man.veraltet} veraltete Manifest-Antworten oder Wiederholungen wurden nicht übernommen.`);
if (LIVE && SCHREIBT.includes(PHASE) && man.kaputt) { console.log('ABBRUCH: Manifest prüfen, unbekannte Historie wird nicht überschrieben.'); process.exit(1); }
const p = plan(alle, man.ids, { budget: BUDGET });
bericht(p, alle);
writeFileSync(PLAN_AUS, JSON.stringify({ am: new Date().toISOString(), zahlen: p.zahlen, varianten: p.varianten, fehler: p.fehler, abwaehlen: p.abwaehlen, aufnehmen: p.aufnehmen, zuruecksetzen: p.zuruecksetzen }));
console.log(`  Plan geschrieben: ${PLAN_AUS}`);

if (PHASE === 'plan') process.exit(p.ok && !man.kaputt ? 0 : 2);

if (PHASE === 'pruefen') {
  if (man.kaputt) { console.log('PRÜFUNG unbekannt: Manifest beschädigt.'); process.exit(2); }
  if (!p.ok) { console.log('\nPRÜFUNG nicht aussagekräftig: der Plan ist nicht erlaubt (siehe oben).'); process.exit(2); }
  const nachId = new Map(alle.map(x => [x.id, x]));
  const falsch = [];
  for (const id of man.ids) { const x = nachId.get(id); if (x && x.aufGoogle === true) falsch.push({ id, handle: x.handle, problem: 'abgewählt, aber noch auf Google' }); }
  const fehlt = [...man.ids].filter(id => !nachId.has(id)).length;
  const zuViel = alle.filter(x => x.aufGoogle === true && !p.drin.has(x.id)).length;
  const varianten = alle.filter(x => x.aufGoogle === true).reduce((s, x) => s + (Number.isFinite(Number(x.varianten)) ? Number(x.varianten) : 0), 0);
  console.log(`\nPRÜFUNG: Varianten auf Google jetzt ${varianten} (Quote 150000) · Manifest ${man.ids.size} Produkte · davon noch auf Google ${falsch.length} (Defekt) · nicht mehr aktiv/gelesen ${fehlt} · auf Google, aber nicht im Schaufenster ${zuViel}`);
  for (const f of falsch.slice(0, 10)) console.log(`    ${f.handle}: ${f.problem}`);
  if (falsch.length) process.exit(3);
  if (zuViel && !ONLY.length) { console.log('  Google trägt noch Produkte ausserhalb des Schaufensters: PHASE=abwaehlen steht aus.'); process.exit(5); }
  process.exit(0);
}

if (PHASE === 'abwaehlen' && LIVE && !bestellt.vollstaendig) { console.log(`ABBRUCH: Die Bestellungen sind unvollständig gelesen (${bestellt.fehler}); ohne sie würden verkaufte Produkte vom Kanal gehen.`); process.exit(1); }
if (PHASE === 'abwaehlen' && LIVE && mitRating < MIN_BEWERTET) { console.log(`ABBRUCH: Nur ${mitRating} Produkte mit Bewertungsfeld gelesen (erwartet über ${MIN_BEWERTET}); ohne sie würden gut bewertete Produkte vom Kanal gehen.`); process.exit(1); }
if (!p.ok && PHASE !== 'zuruecksetzen') process.exit(2);   // die volle Rücknahme darf auch bei verdächtigem Plan laufen: sie stellt nur Eigenes zurück
const art = PHASE === 'abwaehlen' ? 'abwaehlen' : 'aufnehmen';           // Art der Mutation (Unpublish oder Publish)
let ziele = PHASE === 'abwaehlen' ? p.abwaehlen : PHASE === 'aufnehmen' ? p.aufnehmen : p.zuruecksetzen;
if (ONLY.length) {
  ziele = ziele.filter(x => ONLY.includes(x.handle));
  if (!ziele.length) { console.log(`ABBRUCH: ONLY nennt keinen Handle, der in dieser Phase etwas zu tun hat (${ONLY.join(', ')}).`); process.exit(1); }
}
const fehlerAnzahl = liesFehler();
const gesperrt = ziele.filter(x => (fehlerAnzahl.get(x.id) || 0) >= 3);
if (gesperrt.length) console.log(`HINWEIS: ${gesperrt.length} Produkte schlugen schon dreimal fehl und werden übersprungen (${FEHLERDATEI}), zum Beispiel ${gesperrt.slice(0, 3).map(x => x.handle).join(', ')}.`);
const bereit = ziele.filter(x => (fehlerAnzahl.get(x.id) || 0) < 3).slice(0, MAX);
console.log(`\n${PHASE.toUpperCase()}: ${bereit.length} von ${ziele.length} Produkten${bereit.length < ziele.length - gesperrt.length ? ` (MAX ${MAX} erreicht, der Rest folgt im nächsten Lauf)` : ''}`);
if (!LIVE) { console.log('TROCKENLAUF: nichts geschrieben.'); process.exit(0); }
if (!bereit.length) { console.log('Nichts zu tun.'); process.exit(0); }

// Das Manifest muss schreibbar sein, BEVOR das erste Produkt vom Kanal geht (sonst gäbe es abgewählte Produkte ohne Spur).
try {
  mkdirSync(dirname(MANIFEST), { recursive: true });
  if (existsSync(MANIFEST)) { const b = readFileSync(MANIFEST); umbruchNoetig = b.length > 0 && b[b.length - 1] !== 10; }
  appendFileSync(MANIFEST, '');
} catch (e) { console.log(`ABBRUCH: Manifest ${MANIFEST} nicht schreibbar: ${String(e.message).slice(0, 120)}`); process.exit(1); }

let gut = 0, schlecht = 0, runde = 0; const t0 = Date.now();
const nameVon = new Map(bereit.map(x => [x.id, x.handle]));
for (const st of stuecke(bereit.map(x => x.id), STUECK)) {
  // Die Freigabe gilt nicht nur beim Start: wer die Datei löscht, stoppt den Lauf vor dem nächsten Stück (Zweitmeinung Codex 28.10.2026, am Code bestätigt).
  if (LIVE && !existsSync(FREIGABE)) {
    console.log(`ABBRUCH nach ${gut} erfolgreichen: die Freigabedatei ist weg (Stopp). Das nächste Stück wurde nicht begonnen, der Rest bleibt für den nächsten Lauf.`);
    process.exit(4);
  }
  // Absicht VOR dem Aufruf: stürzt der Lauf mitten im Stück ab (oder meldet Shopify einen Teilfehler), bleiben die schon entveröffentlichten Produkte rückholbar.
  if (PHASE === 'abwaehlen') {
    const operationId = randomUUID();
    anhaengen(MANIFEST, st.map(id => manifestZeile(id, undefined, heute(), 'ab-versucht', { operationId })).join('\n') + '\n');
  }
  let antwort;
  try { antwort = await q(mutation(st, art)); }
  catch (e) {
    console.log(`ABBRUCH nach ${gut} erfolgreichen: ${String(e.message).slice(0, 200)} (Drosselung oder Fehler; der nächste Lauf macht weiter; das laufende Stück steht als «ab-versucht» im Manifest, PHASE=pruefen zeigt den echten Stand).`);
    process.exit(4);
  }
  const r = auswerten(antwort, st, art);
  if (r.ok.length && PHASE !== 'abwaehlen') anhaengen(MANIFEST, r.ok.map(id => manifestZeile(id, undefined, heute(), 'auf', { closesOperationId: man.generationen.get(id) })).join('\n') + '\n');
  if (r.fehlgeschlagen.length) appendFileSync(FEHLERDATEI, r.fehlgeschlagen.map(f => `${f.id}\t${heute()}\t${String(f.meldung).replace(/\s+/g, ' ').slice(0, 120)}`).join('\n') + '\n');
  gut += r.ok.length; schlecht += r.fehlgeschlagen.length;
  for (const f of r.fehlgeschlagen.slice(0, 3)) console.log(`  FEHLER ${nameVon.get(f.id)}: ${f.meldung}`);
  if (++runde % 25 === 0) console.log(`  ${gut + schlecht} / ${bereit.length} · erfolgreich ${gut} · Fehler ${schlecht} · ${Math.round((Date.now() - t0) / 1000)} s`);
  if (schlecht > 100 && schlecht / (gut + schlecht) > 0.05) { console.log('ABBRUCH: mehr als 5 % Fehlschläge.'); process.exit(3); }
}
console.log(`FERTIG: erfolgreich ${gut}, Fehler ${schlecht}, ${Math.round((Date.now() - t0) / 1000)} s. Nächster Schritt: PHASE=pruefen.`);
process.exit(schlecht ? 3 : 0);

/**
 * Google-Schaufenster: welche Produkte bleiben auf dem Vertriebskanal «Google & YouTube»?
 *
 * WARUM (Besitzer-Screenshot 28.10.2026, Merchant Center «Needs attention»):
 *   «Shopping ads quota limit reached (outside of CSS program)» und «Over capacity for Shopping ads
 *   (in CSS program)», je 236 000 Produkte (60 %). Produkte darüber sind «Limited» und laufen nicht in
 *   Anzeigen. QUELLE Google Merchant Center Help «Understanding quotas» (abgerufen 28.10.2026):
 *   Standardgrenze 150 000 Artikel je Bereich (Anzeigen in CSS-Ländern, Anzeigen ausserhalb, kostenlose
 *   Einträge); Erhöhung nur bei mindestens 80 % Auslastung, unter 20 % abgelehnten/ausstehenden
 *   Artikeln und ausreichender Leistung; Google nennt als Weg «remove products you no longer intend to
 *   sell or advertise». Ein Artikel ist eine VARIANTE.
 * GEMESSEN 28.10.2026 (Bulk-Abfrage, 56 618 aktive Produkte): 54 745 liegen auf dem Kanal «Google & YouTube»
 *   mit zusammen 514 931 Varianten; 20 433 davon tragen `excluded_destination = ["Shopping_ads"]` (207 114
 *   Varianten), 778 sind Fortura/CH-Lager. Die Auswahl-Läufe fügen jede Nacht Varianten hinzu: die Zahl
 *   wächst, ohne dass ein Produkt dazukommt.
 *
 * DIE REGEL: bleiben darf, was Google zeigen soll, bis die Zahl der Varianten unter dem Budget liegt.
 *   nie      zuerst (auch vor Fortura und vor «bewährt»): Sperrtag (`kanal_sperren.mjs`), keine Google-Kategorie, Lieferbarkeit/Bild negativ
 *            getaggt, offene Prüf-Tags (`PRUEF_TAGS`), schwach bewertet (höchstens 3,8 Sterne bei mindestens 3 Stimmen, wie rating_guard.mjs),
 *            Lizenzname im Titel (`LIZENZ` aus gmc_feed_item.mjs plus `LIZENZ_PLUS`), Variantenzahl unbekannt (Unbekannt ist kein Befund)
 *   Stufe 1  Fortura/CH-Lager (Schweizer Lager, Kostüme): immer, auch mit Ausschlussfeld
 *   Stufe 0  «bewährt»: bestellt (bezahlt oder teilerstattet, nicht storniert, kein Test) ODER mindestens BEWAEHRT_MIN_RATING Sterne bei
 *            mindestens BEWAEHRT_MIN_ANZAHL Bewertungen: immer, auch mit Ausschlussfeld, ohne Kategorie-Deckel (Prüfer 28.10.: ohne diese
 *            Stufe gingen 7 von 14 verkauften Produkten und 904 von 971 gut bewerteten allein wegen des Ausschlussfelds vom Kanal).
 *            ACHTUNG: die Bewertungen sind importierte CJ-Käuferbewertungen (verified_buyer überall false), kein Beleg für LuxeStyle-Nachfrage.
 *   Stufe 2  Marge A oder B (Tags `mengenrabatt-a`/`-b`) ohne Ausschlussfeld: immer (GEMESSEN 28.10.: 4 424 Marge-Produkte tragen das Ausschlussfeld und gehen mit)
 *   Stufe 3  der Rest ohne Ausschlussfeld, bis das Budget voll ist; wenige Varianten zuerst (jede Variante
 *            kostet einen Platz), je Google-Kategorie (zwei Ebenen) höchstens KATEGORIE_DECKEL des Budgets
 *
 * GRENZEN: Das Werkzeug arbeitet NUR innerhalb dessen, was schon auf Google liegt, und nimmt ausschliesslich
 *   zurück, was es selbst abgewählt hat (Manifest). Ein Produkt, das nie auf Google war (Sperrtag, Policy),
 *   wird nie hinzugefügt. WER das Ausschlussfeld schreibt, ist unbekannt (siehe gmc_ausschluss.mjs); ob die
 *   Google-App es beachtet, ist unbelegt: die Regel hängt nicht davon ab, sie entfernt die Produkte vom Kanal.
 */
import { createHash } from 'node:crypto';
import { sperrTags } from './kanal_sperren.mjs';
import { LIZENZ } from './gmc_feed_item.mjs';

export const GOOGLE_PUBLICATION = 'gid://shopify/Publication/302872297857';
/** Wunschgrösse des Schaufensters in Varianten (SETZUNG: 60 000 Varianten Platz unter der Grenze von 150 000 für das Wachstum der nächtlichen Auswahl-Läufe bis zum nächsten Lauf). */
export const BUDGET_VARIANTEN = 90_000;
/** Darüber bricht ein Lauf ab (SETZUNG). */
export const HARTE_GRENZE = 140_000;
/** Darunter ist die Datenlage verdächtig (zum Beispiel fehlende Tags) und der Lauf bricht ab (SETZUNG). */
export const MIN_PRODUKTE = 500;
export const MIN_ZEILEN = 1000;
export const KATEGORIE_DECKEL = 0.15;
/** Unter diesem Budget (Varianten) schreibt das Werkzeug nie (SETZUNG; ein Tippfehler wie BUDGET=9000 würde fast alles abwählen). */
export const MIN_BUDGET = 40_000;
/** Mehr als dieser Anteil der Produkte auf Google soll abgewählt werden: der Plan ist verdächtig (SETZUNG; Erstlauf 28.10.: 51 %). */
export const MAX_ABWAHL_ANTEIL = 0.70;
/** Mehr als dieser Anteil ohne Google-Kategorie: die Lesung war lückenhaft (SETZUNG; gemessen 28.10.: 0,08 %). */
export const MAX_OHNE_KATEGORIE = 0.05;
/** Mehr als dieser Anteil unlesbarer Zeilen: der Lesevorgang war unvollständig, nichts schreiben. */
export const MAX_UNKLAR = 0.02;
/** Zusätzlich zu den Sperrtags (`cj-nicht-versendbar-ch` trifft schon das Muster `nicht-versendbar` in kanal_sperren.mjs). */
export const NEGATIV_TAGS = /^(cj-ausgelistet|bild-zu-klein)$/;
export const PRODUKT_GID = /^gid:\/\/shopify\/Product\/\d+$/;
/**
 * Offene Prüf- und Policy-Tags des Katalogs, die NICHT schon unter die Sperrtags von kanal_sperren.mjs fallen (Prüfer 28.10.: 59 Produkte mit
 * `stecker-unklar`, `versand-pruefen`, `lieferumfang-unklar`, `preis-pruefen-cj-spanne` blieben sonst auf Google). NICHT dabei: `auto-entwurf-0926`, die
 * Charge vom 26.09. ist die einzige Entwurfs-Familie OHNE harten Grund (dropship/BEWERTUNGEN-SICHTBARKEIT-1710.md); ihre 30 aktiven Produkte sind bewusst
 * freigegeben und verkaufen (GEMESSEN 28.10.: Hängematte, Midikleid und Blumenkleid aus Bestellungen #1011/#1013 tragen das Tag).
 * Quelle der Liste: AUSSCHLUSS_TAGS in lib/mengenrabatt.mjs; der Test prüft beide Richtungen (ausser `fortura`/`kostuem`, die hier Stufe 1 bzw. normale Ware sind).
 */
export const PRUEF_TAGS = /^(waffenzubehoer-nicht-verkaufen|stecker-nicht-ch|stecker-unklar|marken-pruefen|waffe-pruefen|versand-pruefen|google-policy-waffen|heilversprechen-risiko|google-kanal-markenware-unklar|lieferumfang-unklar|preis-pruefen-cj-spanne)$/;
/** Schwach bewertet (wie rating_guard.mjs: RATING_MAX 3.8, MIN_COUNT 3): geht vom Kanal, auch wenn es sonst bewährt wäre. */
export const SCHWACH_MAX_RATING = 3.8;
export const SCHWACH_MIN_ANZAHL = 3;
/**
 * Lizenzfiguren, die LIZENZ aus dem Feed nicht kennt (Prüfer 28.10., an allen 56 618 Titeln ohne Fehltreffer gemessen: pikachu 2, garfield 1,
 * pingu 1, wednesday 14, morticia 4, patrick star 1, zelda 1). Der Feed bleibt unverändert; das Schaufenster liest nur Titel, nicht Beschreibungen.
 */
export const LIZENZ_PLUS = /\b(pikachu|garfield|pingu|wednesday|morticia|patrick star|zelda)\b/i;
/** «Bewährt» (SETZUNG): mindestens so viele Sterne bei mindestens so vielen Bewertungen. */
export const BEWAEHRT_MIN_RATING = 4;
export const BEWAEHRT_MIN_ANZAHL = 3;
/** Bestellungen in diesen Zuständen zählen als verkauft (nicht storniert, nicht Test). Vollständig erstattete und nicht bezahlte nicht. */
const BEZAHLT = new Set(['PAID', 'PARTIALLY_REFUNDED']);

/** `reviews.rating` ist JSON (`{"value":"4.5",…}`) oder eine Zahl; `reviews.rating_count` eine ganze Zahl als Text. Unlesbar → null. */
export function ratingAus(ratingWert, anzahlWert) {
  let r = ratingWert;
  if (typeof r === 'string' && r.trim().startsWith('{')) { try { r = JSON.parse(r).value; } catch { return null; } }
  const rating = Number.parseFloat(String(r ?? '')), anzahl = Number.parseInt(String(anzahlWert ?? ''), 10);
  if (!Number.isFinite(rating) || !Number.isFinite(anzahl) || rating <= 0 || anzahl < 1) return null;
  return { rating, anzahl };
}
/** Ist das Produkt bewährt? `p.bestellt` (true/false) und `p.rating`/`p.bewertungen` (Zahl oder null). */
export function bewaehrt(p) {
  if (p.bestellt === true) return true;
  return Number.isFinite(p.rating) && Number.isFinite(p.bewertungen) && p.rating >= BEWAEHRT_MIN_RATING && p.bewertungen >= BEWAEHRT_MIN_ANZAHL;
}
/**
 * Produkt-IDs aus bezahlten Bestellungen. `bestellungen`: [{test, cancelledAt, displayFinancialStatus, lineItems:{nodes:[{product:{id}}], pageInfo:{hasNextPage}}}].
 * Hat eine Bestellung mehr Positionen als gelesen, ist die Liste unvollständig (`vollstaendig:false`): wer sich darauf verlässt, schreibt nicht.
 */
export function bestellteIds(bestellungen) {
  const ids = new Set(); let vollstaendig = true;
  for (const b of bestellungen || []) {
    if (!b || b.test || b.cancelledAt || !BEZAHLT.has(b.displayFinancialStatus)) continue;
    if (b.lineItems?.pageInfo?.hasNextPage) vollstaendig = false;
    for (const n of b.lineItems?.nodes || []) { const id = n?.product?.id; if (PRODUKT_GID.test(String(id))) ids.add(id); }
  }
  return { ids, vollstaendig };
}

const hatTag = (p, t) => Array.isArray(p.tags) && p.tags.includes(t);

/**
 * Schliesst das Feld `excluded_destination` Shopping-Anzeigen aus? Nur eine Liste MIT «Shopping_ads» zählt; leer, «[]» und
 * andere Ziele (Local_inventory_ads, Free_listings) schliessen sie nicht aus (Prüfer 28.10., heute 0 Fälle). Ein unlesbarer
 * Wert gilt vorsichtshalber als Ausschluss (das Produkt bleibt dann vom Kanal, rückholbar).
 */
export function ausschlussGilt(wert) {
  if (wert === null || wert === undefined || String(wert).trim() === '') return false;
  try { const v = JSON.parse(String(wert)); return Array.isArray(v) ? v.includes('Shopping_ads') : true; } catch { return true; }
}
const katSchluessel = p => String(p.kategorie || '').split(' > ').slice(0, 2).join(' > ');

/** Stufe 0 bis 3 oder null (mit Grund). Reihenfolge ist Absicht: Sperren zuerst (auch vor Fortura und vor «bewährt»), dann Fortura, dann bewährt, dann das Ausschlussfeld. */
export function stufe(p) {
  const tags = Array.isArray(p.tags) ? p.tags : [];
  if (!p.kategorie) return { stufe: null, grund: 'keine-google-kategorie' };
  if (sperrTags(tags).length) return { stufe: null, grund: 'sperrtag' };
  if (tags.some(t => NEGATIV_TAGS.test(t))) return { stufe: null, grund: 'nicht-lieferbar-oder-bild' };
  if (tags.some(t => PRUEF_TAGS.test(t))) return { stufe: null, grund: 'pruef-tag' };
  if (Number.isFinite(p.rating) && Number.isFinite(p.bewertungen) && p.rating <= SCHWACH_MAX_RATING && p.bewertungen >= SCHWACH_MIN_ANZAHL) return { stufe: null, grund: 'schwach-bewertet' };
  if (p.titel && (LIZENZ.test(String(p.titel)) || LIZENZ_PLUS.test(String(p.titel)))) return { stufe: null, grund: 'lizenz-titel' };
  if (hatTag(p, 'fortura') || hatTag(p, 'ch-lager')) return { stufe: 1 };
  if (bewaehrt(p)) return { stufe: 0 };
  if (ausschlussGilt(p.ausschluss)) return { stufe: null, grund: 'ausschluss-shopping-ads' };
  if (hatTag(p, 'mengenrabatt-a') || hatTag(p, 'mengenrabatt-b')) return { stufe: 2 };
  return { stufe: 3 };
}

/**
 * Wählt das Schaufenster. `zeilen`: [{id, handle, titel, tags, varianten, kategorie, ausschluss, bestellt, rating, bewertungen}].
 * @returns {{drin: Map<string, number>, draussen: Array<{id:string, grund:string}>, zahlen: object}}
 */
export function waehle(zeilen, opt = {}) {
  const budget = opt.budget ?? BUDGET_VARIANTEN;
  const deckel = Math.ceil((opt.katDeckel ?? KATEGORIE_DECKEL) * budget);
  const stufen = { 0: [], 1: [], 2: [], 3: [] };
  const draussen = [];
  for (const p of zeilen) {
    const v = Number(p.varianten);
    if (!Number.isFinite(v) || v < 1) { draussen.push({ id: p.id, grund: 'varianten-unbekannt' }); continue; }
    const s = stufe(p);
    if (s.stufe === null) { draussen.push({ id: p.id, grund: s.grund }); continue; }   // Stufe 0 ist gültig (und falsy)
    stufen[s.stufe].push({ ...p, v });
  }
  const drin = new Map();
  const proKat = new Map();
  const summen = { 0: 0, 1: 0, 2: 0, 3: 0 };
  const nimm = (p, s) => {
    drin.set(p.id, s); summen[s] += p.v;
    const k = katSchluessel(p); proKat.set(k, (proKat.get(k) || 0) + p.v);
  };
  for (const s of [0, 1, 2]) for (const p of stufen[s]) nimm(p, s);
  const rest = stufen[3].sort((a, b) => a.v - b.v || String(a.handle).localeCompare(String(b.handle)) || String(a.id).localeCompare(String(b.id)));
  let gesamt = summen[0] + summen[1] + summen[2];
  for (const p of rest) {
    if (gesamt + p.v > budget) { draussen.push({ id: p.id, grund: 'budget' }); continue; }
    if ((proKat.get(katSchluessel(p)) || 0) + p.v > deckel) { draussen.push({ id: p.id, grund: 'kategorie-deckel' }); continue; }
    nimm(p, 3); gesamt += p.v;
  }
  return {
    drin, draussen,
    zahlen: {
      budget, katDeckel: deckel,
      produkte: { 0: stufen[0].length, 1: stufen[1].length, 2: stufen[2].length, 3: stufen[3].length },
      drin: { 0: [...drin.values()].filter(s => s === 0).length, 1: [...drin.values()].filter(s => s === 1).length, 2: [...drin.values()].filter(s => s === 2).length, 3: [...drin.values()].filter(s => s === 3).length },
      varianten: { 0: summen[0], 1: summen[1], 2: summen[2], 3: summen[3], gesamt },
    },
  };
}

/** Erste Zeilen einer Liste je Grund, damit eine Zahl nie ohne Beispiele steht. */
export function zaehleGruende(liste) {
  const m = {};
  for (const x of liste) m[x.grund] = (m[x.grund] || 0) + 1;
  return m;
}

/**
 * Der Plan: wer geht vom Kanal, wer darf zurück, und ob der Lauf überhaupt erlaubt ist.
 * `aufGoogle` muss true oder false sein; alles andere (null, undefined) ist «unklar» und wird nie angefasst.
 * `manifest`: Set der Produkt-IDs, die dieses Werkzeug früher abgewählt hat.
 */
export function plan(zeilen, manifest = new Set(), opt = {}) {
  const fehler = [];
  const { drin, draussen, zahlen } = waehle(zeilen, opt);
  const gruende = new Map(draussen.map(d => [d.id, d.grund]));
  // «Unklar» = nie anfassen: Kanalstatus nicht true/false, fremde ID oder unbekannte Variantenzahl (Unbekannt ist kein Befund, Prüfer 28.10.: 701 Zeilen ohne variantsCount wurden abgewählt)
  const klar = p => typeof p.aufGoogle === 'boolean' && PRODUKT_GID.test(String(p.id)) && Number.isFinite(Number(p.varianten)) && Number(p.varianten) >= 1;
  const unklar = zeilen.filter(p => !klar(p));
  const abwaehlen = [];
  const aufnehmen = [];
  const zuruecksetzen = [];
  for (const p of zeilen) {
    if (!klar(p)) continue;
    // Volle Rücknahme: alles, was wir (laut Manifest) abgewählt haben und das nicht mehr auf Google liegt, ausser mit Sperrtag
    if (p.aufGoogle === false && manifest.has(p.id) && !sperrTags(p.tags || []).length) zuruecksetzen.push({ id: p.id, handle: p.handle });
    if (p.aufGoogle === true && !drin.has(p.id)) abwaehlen.push({ id: p.id, handle: p.handle, grund: gruende.get(p.id) || 'unbekannt', varianten: Number(p.varianten) || 0 });
    if (p.aufGoogle === false && manifest.has(p.id) && drin.has(p.id)) aufnehmen.push({ id: p.id, handle: p.handle, stufe: drin.get(p.id) });
  }
  // Wie viele Varianten liegen NACH dem Lauf auf Google? (nur Produkte mit bekannter Variantenzahl)
  const nachher = zeilen.reduce((s, p) => {
    const v = Number(p.varianten);
    if (!Number.isFinite(v)) return s;
    const bleibt = p.aufGoogle === true && drin.has(p.id);
    const kommt = p.aufGoogle === false && manifest.has(p.id) && drin.has(p.id);
    return s + (bleibt || kommt ? v : 0);
  }, 0);
  const vorher = zeilen.reduce((s, p) => s + (p.aufGoogle === true && Number.isFinite(Number(p.varianten)) ? Number(p.varianten) : 0), 0);
  if (zeilen.length < MIN_ZEILEN) fehler.push(`zu-wenige-zeilen: ${zeilen.length} (Lesevorgang unvollständig?)`);
  if (zeilen.length && unklar.length / zeilen.length > MAX_UNKLAR) fehler.push(`zu-viele-unklare-zeilen: ${unklar.length} von ${zeilen.length}`);
  if (drin.size < MIN_PRODUKTE) fehler.push(`schaufenster-zu-klein: ${drin.size} Produkte (Mindestens ${MIN_PRODUKTE}; fehlen Tags?)`);
  if (nachher > HARTE_GRENZE) fehler.push(`schaufenster-zu-gross: ${nachher} Varianten nach dem Lauf (Grenze ${HARTE_GRENZE})`);
  const aufGoogleJetzt = zeilen.filter(p => klar(p) && p.aufGoogle === true).length;
  if (aufGoogleJetzt && abwaehlen.length / aufGoogleJetzt > MAX_ABWAHL_ANTEIL) fehler.push(`zu-viele-abwaehlen: ${abwaehlen.length} von ${aufGoogleJetzt} Produkten auf Google (Grenze ${Math.round(MAX_ABWAHL_ANTEIL * 100)} %; lückenhafte Lesung oder falsches BUDGET?)`);
  if (zeilen.length && zeilen.filter(p => !p.kategorie).length / zeilen.length > MAX_OHNE_KATEGORIE) fehler.push(`zu-viele-ohne-kategorie: ${zeilen.filter(p => !p.kategorie).length} von ${zeilen.length} Zeilen (Metafeld nicht gelesen?)`);
  return {
    ok: fehler.length === 0, fehler, abwaehlen, aufnehmen, zuruecksetzen, zahlen,
    varianten: { vorher, nachher },
    gruende: zaehleGruende(abwaehlen), unklar: unklar.length, drin, draussen,
  };
}

/** Teilt in Stücke zu n. */
export function stuecke(liste, n) {
  if (!Number.isInteger(n) || n < 1) throw new Error('n muss eine ganze Zahl >= 1 sein');
  const aus = [];
  for (let i = 0; i < liste.length; i += n) aus.push(liste.slice(i, i + n));
  return aus;
}

/** Mutation für ein Stück Produkte. Jede ID wird geprüft: sie landet im Text der Abfrage. */
export function mutation(ids, art) {
  if (art !== 'abwaehlen' && art !== 'aufnehmen') throw new Error(`unbekannte Art: ${art}`);
  const name = art === 'abwaehlen' ? 'publishableUnpublish' : 'publishablePublish';
  return 'mutation{ ' + ids.map((id, i) => {
    if (!PRODUKT_GID.test(String(id))) throw new Error(`ungültige Produkt-ID: ${id}`);
    return `a${i}: ${name}(id:"${id}", input:[{publicationId:"${GOOGLE_PUBLICATION}"}]){ userErrors{ field message } }`;
  }).join(' ') + ' }';
}

/** Antwort einer Mutation lesen: nur ein belegter Erfolg zählt (keine userErrors, Alias da). */
export function auswerten(antwort, ids, art) {
  const name = art === 'abwaehlen' ? 'publishableUnpublish' : 'publishablePublish';
  const ok = []; const fehlgeschlagen = [];
  ids.forEach((id, i) => {
    const e = antwort?.[`a${i}`];
    const ue = e?.userErrors;
    if (!e || !Array.isArray(ue)) fehlgeschlagen.push({ id, meldung: `${name}: keine Antwort` });
    else if (ue.length) fehlgeschlagen.push({ id, meldung: ue.map(u => u.message).join('; ').slice(0, 160) });
    else ok.push(id);
  });
  return { ok, fehlgeschlagen };
}

/**
 * Legacy-Zeilen bleiben lesbar. Neue Absichten tragen eine Generation; eine Rücknahme
 * schliesst nur diese Generation. Verspätete oder alte Antworten löschen nichts Neueres.
 */
const VORGANG = /^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$/;
const eigen = (o, k) => Object.prototype.hasOwnProperty.call(o, k);
const gueltigerVorgang = v => typeof v === 'string' && VORGANG.test(v);

export function parseManifest(text) {
  const offen = new Map(), geschuetzt = new Set(), gesehen = new Map(), geschlossen = new Map();
  let kaputt = 0, veraltet = 0, zeile = 0;
  for (const z of String(text ?? '').replace(/^\uFEFF/, '').split('\n')) {
    zeile++;
    if (!z.trim()) continue;
    let o;
    try { o = JSON.parse(z); } catch { kaputt++; continue; }
    if (!o || typeof o.id !== 'string' || !PRODUKT_GID.test(o.id)) { kaputt++; continue; }
    const id = o.id, aktion = o.aktion ?? 'ab';
    const neu = eigen(o, 'operationId') || eigen(o, 'closesOperationId');
    const unklar = () => {
      kaputt++; geschuetzt.add(id);
      if (!offen.has(id)) offen.set(id, { generation: null });
    };
    if (!['ab', 'ab-versucht', 'auf'].includes(aktion)) {
      if (neu) unklar(); else kaputt++;
      continue;
    }
    if (aktion === 'auf') {
      if (eigen(o, 'operationId') || neu && !gueltigerVorgang(o.closesOperationId)) { unklar(); continue; }
      const aktuell = offen.get(id);
      if (!neu) {
        if (geschuetzt.has(id)) { veraltet++; continue; }
        offen.delete(id);
      } else {
        geschuetzt.add(id);
        if (aktuell?.generation === o.closesOperationId) {
          offen.delete(id);
          if (!geschlossen.has(id)) geschlossen.set(id, new Set());
          geschlossen.get(id).add(o.closesOperationId);
        } else if (gesehen.get(id)?.has(o.closesOperationId) || geschlossen.get(id)?.has(o.closesOperationId)) {
          veraltet++;
        } else {
          unklar();
        }
      }
      continue;
    }
    if (neu && (eigen(o, 'closesOperationId') || !gueltigerVorgang(o.operationId))) { unklar(); continue; }
    let generation;
    if (neu) {
      geschuetzt.add(id);
      if (!gesehen.has(id)) gesehen.set(id, new Set());
      if (gesehen.get(id).has(o.operationId)) { veraltet++; continue; }
      gesehen.get(id).add(o.operationId);
      generation = o.operationId;
    } else {
      generation = `legacy:${zeile}:${createHash('sha256').update(z).digest('hex').slice(0, 24)}`;
      if (!gesehen.has(id)) gesehen.set(id, new Set());
      gesehen.get(id).add(generation);
    }
    offen.set(id, { generation });
  }
  return { ids: new Set(offen.keys()), generationen: new Map([...offen].map(([id, o]) => [id, o.generation])), kaputt, veraltet };
}

export function manifestZeile(id, handle, datum, aktion = 'ab', generation = undefined) {
  if (generation === undefined) return JSON.stringify({ id, handle, am: datum, aktion });
  if (!generation || typeof generation !== 'object' || Array.isArray(generation)) throw new Error('Manifest: Vorgang fehlt');
  const k = aktion === 'auf' ? 'closesOperationId' : 'operationId';
  if (!['ab', 'ab-versucht', 'auf'].includes(aktion) || !gueltigerVorgang(generation[k]) || Object.keys(generation).some(x => x !== k)) {
    throw new Error('Manifest: ungültige Vorgangsbindung');
  }
  return JSON.stringify({ id, handle, am: datum, aktion, [k]: generation[k] });
}

