// --- Generationsgebundene Rücknahme: eine alte Bestätigung löscht niemals eine neuere Absicht.
{
  const id = 'gid://shopify/Product/77';
  const ab = op => manifestZeile(id, undefined, '2026-10-28', 'ab-versucht', { operationId: op });
  const auf = op => manifestZeile(id, undefined, '2026-10-28', 'auf', { closesOperationId: op });
  const lies = (...z) => parseManifest(z.join('\n'));
  const a = lies(ab('A'));
  pruef('Generation A: offen mit Kennung', [a.ids.has(id), a.generationen.get(id), a.kaputt], [true, 'A', 0]);
  const seriell = lies(ab('A'), auf('A'));
  pruef('seriell A zurück: geschlossen', [seriell.ids.has(id), seriell.kaputt], [false, 0]);
  const spaet = lies(ab('A'), ab('B'), auf('A'));
  pruef('späte Rücknahme A löscht B nicht', [spaet.ids.has(id), spaet.generationen.get(id), spaet.veraltet, spaet.kaputt], [true, 'B', 1, 0]);
  const fertig = lies(ab('A'), ab('B'), auf('A'), auf('B'));
  pruef('erst belegte Rücknahme B schliesst B', [fertig.ids.has(id), fertig.kaputt], [false, 0]);
  const duplikat = lies(ab('A'), ab('B'), ab('A'));
  pruef('doppelte alte Absicht setzt Generation nicht zurück', [duplikat.ids.has(id), duplikat.generationen.get(id), duplikat.veraltet], [true, 'B', 1]);
  const geschlossen = lies(ab('A'), auf('A'), ab('A'));
  pruef('doppelte schon geschlossene Absicht öffnet nicht erneut', [geschlossen.ids.has(id), geschlossen.veraltet], [false, 1]);
  const doppeltAuf = lies(ab('A'), auf('A'), auf('A'));
  pruef('doppelte Bestätigung bleibt geschlossen', [doppeltAuf.ids.has(id), doppeltAuf.kaputt, doppeltAuf.veraltet], [false, 0, 1]);
  const legacy = manifestZeile(id, undefined, 'd', 'ab');
  const lg = lies(legacy);
  const legacyZu = lies(legacy, auf(lg.generationen.get(id)));
  pruef('Legacy-Absicht kann mit exakt gebundener Kennung zurück', [legacyZu.ids.has(id), legacyZu.kaputt], [false, 0]);
  const legacySpaet = lies(legacy, ab('B'), auf(lg.generationen.get(id)));
  pruef('gebundene alte Legacy-Rücknahme erhält B', [legacySpaet.ids.has(id), legacySpaet.generationen.get(id), legacySpaet.kaputt], [true, 'B', 0]);
  const ungeordnet = lies(ab('A'), manifestZeile(id, undefined, 'd', 'auf'));
  pruef('ungebundene Legacy-Rücknahme erhält geschützte Generation', [ungeordnet.ids.has(id), ungeordnet.generationen.get(id), ungeordnet.veraltet], [true, 'A', 1]);
  const orphan = lies(auf('nie-gesehen'));
  pruef('verwaiste Rücknahme wird unbekannt statt geschlossen', [orphan.ids.has(id), orphan.kaputt], [true, 1]);
  const mismatch = lies(ab('A'), auf('nie-gesehen'));
  pruef('unbekannte Rücknahme erhält A und markiert Defekt', [mismatch.ids.has(id), mismatch.generationen.get(id), mismatch.kaputt], [true, 'A', 1]);
  const kaputt = lies(ab('A'), JSON.stringify({ id, aktion: 'ab-versucht', operationId: '' }), manifestZeile(id, undefined, 'd', 'auf'));
  pruef('kaputte Generation plus Legacy-Auf verliert bekannte Identität nicht', [kaputt.ids.has(id), kaputt.generationen.get(id), kaputt.kaputt], [true, 'A', 1]);
  pruef('falscher ID-Typ wird nicht koerziert', lies(JSON.stringify({ id: [id], aktion: 'ab-versucht', operationId: 'A' })).kaputt, 1);
  wirft('Absicht braucht gültige operationId', () => ab(''), 'Vorgangsbindung');
  wirft('Aufnahme darf keine operationId statt closesOperationId tragen', () => manifestZeile(id, undefined, 'd', 'auf', { operationId: 'A' }), 'Vorgangsbindung');
}

