  ist('Trefferprobe: Messgerät, ganze Wörter zählen und Teilwörter nicht', [treffer('Zeig den Stand', 'stand'), treffer('Wie viel Lagerbestand', 'stand'), treffer('git status!', 'git status')], [true, false, true]);
