  const t = skillText('lieferbar');
  ist('lieferbar: die Kostenangabe im Skill ist die gemessene Spanne (50 bis 75 Aufrufe bei 25 Handles, bis zu dreimal je Handle)', [t.includes(`${a25.ohneAnmeldung} bis ${b25.ohneAnmeldung} Aufrufe`), t.includes('bis zu dreimal bei CJ'), (b25.ohneAnmeldung ?? 0) / 25], [true, true, 3]);
  const leer = waechter([], 'variante');
  ist('lieferbar gemessen (Fund 4): ein LEERES HANDLES wird ignoriert, der Wächter durchsucht den Katalog und prüft bis zu 40 Produkte bei CJ', [leer.code, leer.bericht?.gelesen, leer.bericht?.geprueft, leer.zaehler?.shopify], [0, 50, 40, 1]);
  ist('lieferbar: der Skill nennt genau diese Folge («bis zu 40 Prüfungen bei CJ»)', t.includes(`bis zu ${leer.bericht?.geprueft} Prüfungen bei CJ`), true);
  rmSync(wurzel, { recursive: true, force: true });
}

fertig();

#!/usr/bin/env node
/**
 * Test des Workflows .github/workflows/gmc-schaufenster.yml: nicht das YAML, sondern die Regeln, die es durchsetzen muss.
 * Der Schritt «Modus und Freigabe festlegen» wird aus der Datei gelesen und in bash mit Attrappen-Dateien ausgeführt.
 *
 *   - Zeitplan ohne Dauerfreigabe: nur prüfen, nie schreiben.
 *   - Zeitplan schreibt nur, wenn BEIDE Dateien liegen (GMC-SCHAUFENSTER-FREI.txt und GMC-SCHAUFENSTER-TAEGLICH-FREI.txt).
 *   - Von Hand: jeder schreibende Modus braucht GMC-SCHAUFENSTER-FREI.txt.
 *   - Eingaben nur aus der Liste, die Höchstzahl nur «alle» oder Ziffern; nichts landet ungeprüft in einem Befehl.
 *   - LIVE kommt nur aus dem Modus-Schritt, nie als feste Einstellung.
 */
import { spawnSync } from 'node:child_process';
import { mkdtempSync, mkdirSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';

let ok = 0, fehl = 0;
const wahr = (name, bed, info = '') => { if (bed) ok++; else { fehl++; console.log(`✗ ${name}${info ? ' · ' + info : ''}`); } };

const WF = readFileSync(fileURLToPath(new URL('../.github/workflows/gmc-schaufenster.yml', import.meta.url)), 'utf8');

/** Der Text (run: |) eines Schritts, eingerückt entfernt. */
function schritt(name) {
  const m = WF.split(/^      - /m).find(b => b.startsWith(`name: ${name}`));
  if (!m) return null;
  const lines = m.split('\n');
  const i = lines.findIndex(l => /^        run: \|\s*$/.test(l));
  if (i < 0) return null;
  const body = [];
  for (const l of lines.slice(i + 1)) { if (l && !l.startsWith('          ')) break; body.push(l.replace(/^ {10}/, '')); }
  return body.join('\n');
}

const SKRIPT = schritt('Modus und Freigabe festlegen');
wahr('Schritt «Modus und Freigabe festlegen» mit run-Block gefunden', typeof SKRIPT === 'string' && SKRIPT.length > 300, String(SKRIPT?.length));

/** Führt den Modus-Schritt aus. dateien: welche Freigabedateien liegen. */
function lauf({ ereignis, modus = '', max = '', frei = false, taeglich = false, ref = 'refs/heads/main', standard = 'main' }) {
  const d = mkdtempSync(join(tmpdir(), 'gmcwf-'));
  try {
    mkdirSync(join(d, 'dropship'));
    if (frei) writeFileSync(join(d, 'dropship/GMC-SCHAUFENSTER-FREI.txt'), 'x');
    if (taeglich) writeFileSync(join(d, 'dropship/GMC-SCHAUFENSTER-TAEGLICH-FREI.txt'), 'x');
    const out = join(d, 'out.txt'), env = join(d, 'env.txt');
    writeFileSync(out, ''); writeFileSync(env, '');
    const r = spawnSync('bash', ['-eo', 'pipefail', '-c', SKRIPT], {
      cwd: d, encoding: 'utf8', timeout: 20000,
      env: { PATH: process.env.PATH, EREIGNIS: ereignis, QUELL_REF: ref, STANDARDZWEIG: standard, MODUS_EINGABE: modus, MAX_EINGABE: max, GITHUB_OUTPUT: out, GITHUB_ENV: env },
    });
    const o = Object.fromEntries(readFileSync(out, 'utf8').split('\n').filter(Boolean).map(z => z.split(/=(.*)/s).slice(0, 2)));
    return { rc: r.status, o, text: (r.stdout || '') + (r.stderr || '') };
  } finally { rmSync(d, { recursive: true, force: true }); }
}

if (SKRIPT) {
  // Zeitplan
  let r = lauf({ ereignis: 'schedule' });
  wahr('Zeitplan ohne Freigabedateien: prüfen, schreibt nicht', r.rc === 0 && r.o.modus === 'pruefen' && r.o.live === '0', JSON.stringify(r.o));
  wahr('Zeitplan ohne Dauerfreigabe nennt den Grund als Hinweis', /Zeitplan liest nur/.test(r.text));
  r = lauf({ ereignis: 'schedule', frei: true });
  wahr('Zeitplan mit nur FREI.txt (Einmalfreigabe): prüfen, schreibt nicht', r.rc === 0 && r.o.modus === 'pruefen' && r.o.live === '0', JSON.stringify(r.o));
  r = lauf({ ereignis: 'schedule', taeglich: true });
  wahr('Zeitplan mit nur TAEGLICH-FREI.txt (ohne FREI.txt): prüfen, schreibt nicht', r.rc === 0 && r.o.modus === 'pruefen' && r.o.live === '0', JSON.stringify(r.o));
  r = lauf({ ereignis: 'schedule', frei: true, taeglich: true });
  wahr('Zeitplan mit beiden Dateien: abwählen, schreibt', r.rc === 0 && r.o.modus === 'abwaehlen' && r.o.live === '1' && r.o.max === 'alle', JSON.stringify(r.o));
  r = lauf({ ereignis: 'schedule', frei: true, taeglich: true, modus: 'zuruecksetzen', max: '5' });
  wahr('Zeitplan ignoriert Eingaben (nie «zuruecksetzen» aus dem Zeitplan)', r.o.modus === 'abwaehlen', JSON.stringify(r.o));

  // Von Hand
  for (const m of ['plan', 'pruefen']) {
    r = lauf({ ereignis: 'workflow_dispatch', modus: m });
    wahr(`Hand: ${m} liest nur und braucht keine Freigabe`, r.rc === 0 && r.o.modus === m && r.o.live === '0', JSON.stringify(r.o));
  }
  for (const m of ['abwaehlen', 'aufnehmen', 'zuruecksetzen']) {
    r = lauf({ ereignis: 'workflow_dispatch', modus: m });
    wahr(`Hand: ${m} ohne FREI.txt bricht ab, schreibt nichts`, r.rc === 1 && !r.o.live && /Nicht freigegeben/.test(r.text), `rc ${r.rc} ${JSON.stringify(r.o)}`);
    r = lauf({ ereignis: 'workflow_dispatch', modus: m, frei: true });
    wahr(`Hand: ${m} mit FREI.txt schreibt`, r.rc === 0 && r.o.modus === m && r.o.live === '1', JSON.stringify(r.o));
  }
  r = lauf({ ereignis: 'workflow_dispatch', modus: 'abwaehlen', frei: true, max: '50' });
  wahr('Hand: Höchstzahl als Ziffern wird übernommen', r.rc === 0 && r.o.max === '50', JSON.stringify(r.o));
  r = lauf({ ereignis: 'workflow_dispatch', modus: 'plan' });
  wahr('Hand: leere Höchstzahl wird zu «alle»', r.o.max === 'alle', JSON.stringify(r.o));

  // Eingaben
  for (const bose of ['', 'loeschen', 'abwaehlen; echo x', '$(id)', 'plan\nabwaehlen', 'ABWAEHLEN']) {
    r = lauf({ ereignis: 'workflow_dispatch', modus: bose, frei: true });
    wahr(`Hand: unzulässiger Modus «${bose.replace(/\n/g, '\\n')}» bricht ab`, r.rc === 1 && !r.o.live, `rc ${r.rc} ${JSON.stringify(r.o)}`);
  }
  for (const bose of ['5; echo x', '-1', '1e3', 'ALLE', '$(id)', '5 6', 'unbegrenzt']) {
    r = lauf({ ereignis: 'workflow_dispatch', modus: 'plan', max: bose });
    wahr(`Hand: unzulässige Höchstzahl «${bose}» bricht ab`, r.rc === 1 && !r.o.max, `rc ${r.rc} ${JSON.stringify(r.o)}`);
  }
}

// Der Schritt «Manifest committen» in einem Wegwerf-Repo mit lokalem Origin (Fund der Codex-Zweitmeinung 28.10.2026: git add mit einer
// Fehlerdatei, die es nicht gibt, bricht mit Exit 128 ab und das Manifest bliebe ohne Commit).
const COMMIT = schritt('Manifest committen (auch nach Teilfehlern)');
wahr('Schritt «Manifest committen» mit run-Block gefunden', typeof COMMIT === 'string' && COMMIT.length > 300, String(COMMIT?.length));
function commitLauf({ manifest, fehler, vorhanden = false }) {
  const d = mkdtempSync(join(tmpdir(), 'gmcwf-git-'));
  const sh = (cmd, cwd = d) => spawnSync('bash', ['-ec', cmd], { cwd, encoding: 'utf8', timeout: 30000, env: { PATH: process.env.PATH, HOME: d, GIT_CONFIG_NOSYSTEM: '1' } });
  try {
    sh('git init -q --bare origin.git && git clone -q origin.git arbeit 2>/dev/null; cd arbeit && git config user.email t@t && git config user.name t && git checkout -q -b main && mkdir -p dropship automation && echo x > automation/a.txt'
      + (vorhanden ? " && echo '{\"id\":\"alt\"}' > dropship/gmc_schaufenster_manifest.jsonl" : '') + ' && git add -- automation/a.txt dropship && git commit -q -m init && git push -q origin main');
    const w = join(d, 'arbeit');
    if (manifest) writeFileSync(join(w, 'dropship/gmc_schaufenster_manifest.jsonl'), (vorhanden ? '{"id":"alt"}\n' : '') + '{"id":"gid://shopify/Product/1","aktion":"ab-versucht"}\n');
    if (fehler) writeFileSync(join(w, 'dropship/gmc_schaufenster_fehler.txt'), 'gid://shopify/Product/1\t2026-10-28\tfake\n');
    const r = spawnSync('bash', ['-eo', 'pipefail', '-c', COMMIT], { cwd: w, encoding: 'utf8', timeout: 30000, env: { PATH: process.env.PATH, HOME: d, ZIEL: 'main', GIT_CONFIG_NOSYSTEM: '1' } });
    const oben = sh('git log --oneline main | head -3; git show --stat --format= main | tail -3', join(d, 'origin.git'));
    return { rc: r.status, text: (r.stdout || '') + (r.stderr || ''), oben: oben.stdout };
  } finally { rmSync(d, { recursive: true, force: true }); }
}
if (COMMIT) {
  let r = commitLauf({ manifest: true, fehler: false });
  wahr('Commit: nur das Manifest vorhanden (keine Fehlerliste) wird committet und gepusht', r.rc === 0 && /Manifest, 1 neue Zeilen/.test(r.oben) && /gmc_schaufenster_manifest\.jsonl/.test(r.oben), `rc ${r.rc} ${r.text.slice(-200)} ${r.oben}`);
  r = commitLauf({ manifest: true, fehler: true });
  wahr('Commit: Manifest und Fehlerliste zusammen', r.rc === 0 && /gmc_schaufenster_manifest\.jsonl/.test(r.oben) && /gmc_schaufenster_fehler\.txt/.test(r.oben), `rc ${r.rc} ${r.oben}`);
  r = commitLauf({ manifest: false, fehler: true });
  wahr('Commit: nur die Fehlerliste vorhanden', r.rc === 0 && /gmc_schaufenster_fehler\.txt/.test(r.oben), `rc ${r.rc} ${r.text.slice(-200)} ${r.oben}`);
  r = commitLauf({ manifest: false, fehler: false });
  wahr('Commit: nichts geändert → Exit 0 ohne Commit', r.rc === 0 && /Kein Manifest-Update/.test(r.text) && !/Manifest, /.test(r.oben), `rc ${r.rc} ${r.text.slice(-200)}`);
}

// Aufbau des Workflows
wahr('Zeitplan vorhanden (täglich 04:41 UTC, nicht beim Auswahl-Lauf um 21:50)', /schedule:\s*\n\s*- cron: '41 4 \* \* \*'/.test(WF));
wahr('LIVE ist nirgends fest auf 1 gesetzt (kommt nur aus dem Modus-Schritt)', !/LIVE:\s*['"]?1['"]?\s*$/m.test(WF) && /LIVE: \$\{\{ steps\.modus\.outputs\.live \}\}/.test(WF));
wahr('Nachprüfung läuft ohne LIVE', /PHASE: pruefen\n\s+LIVE: '0'/.test(WF));
wahr('Eingaben gelangen nur über env in den Job (jede Zeile mit inputs.* ist MODUS_EINGABE oder MAX_EINGABE)', WF.split('\n').filter(l => /\$\{\{\s*inputs\./.test(l) && !/^\s+(MODUS_EINGABE|MAX_EINGABE):/.test(l)).length === 0);
wahr('Sparse-Checkout enthält Manifest, Fehlerliste und beide Freigabedateien', ['gmc_schaufenster_manifest.jsonl', 'gmc_schaufenster_fehler.txt', 'GMC-SCHAUFENSTER-FREI.txt', 'GMC-SCHAUFENSTER-TAEGLICH-FREI.txt'].every(n => WF.includes('/dropship/' + n)));
wahr('Nur ein Lauf zugleich (concurrency), ohne Abbruch eines laufenden', /concurrency:\s*\n\s*group: gmc-schaufenster\s*\n\s*cancel-in-progress: false/.test(WF));

wahr('Manifest und Fehlerliste werden mit Union-Merge zurückgelegt', /gmc_schaufenster_manifest\.jsonl merge=union/.test(WF) && /gmc_schaufenster_fehler\.txt merge=union/.test(WF));
wahr('Manifest wird auch nach Teilfehlern committet (always) und nur wenn der Lauf schrieb', /name: Manifest committen[^\n]*\n\s+if: \$\{\{ always\(\) && steps\.modus\.outputs\.live == '1' \}\}/.test(WF));
wahr('Commit trägt [skip ci] (kein Test-Lauf für Manifest-Zeilen)', /\[skip ci\]/.test(WF));


// Zusätzliche Regeln: echte extrahierte Shellblöcke, ausschliesslich lokale Attrappen.
for (const m of ['abwaehlen', 'aufnehmen', 'zuruecksetzen']) {
  const r = lauf({ ereignis: 'workflow_dispatch', modus: m, frei: true, ref: 'refs/heads/fremd' });
  wahr(`Schreibmodus ${m} auf fremdem Zweig gesperrt vor live-Ausgabe`, r.rc === 1 && !r.o.live && /Standardzweig/.test(r.text), JSON.stringify(r));
}
{
  const r = lauf({ ereignis: 'workflow_dispatch', modus: 'plan', ref: 'refs/heads/fremd' });
  wahr('Lesemodus darf fremden Zweig prüfen', r.rc === 0 && r.o.live === '0');
  const r2 = lauf({ ereignis: 'workflow_dispatch', modus: 'abwaehlen', frei: true, standard: '', ref: 'refs/heads/main' });
  wahr('Unbekannter Standardzweig sperrt Schreiben', r2.rc === 1 && !r2.o.live);
  for (const f of ['modus', 'max']) {
    const r3 = lauf({ ereignis: 'workflow_dispatch', modus: f === 'modus' ? 'x\n::error title=injiziert::TEST' : 'plan', max: f === 'max' ? '3\n::error title=injiziert::TEST' : '' });
    wahr(`Ungültige Eingabe ${f} erzeugt keine zusätzliche Workflow-Kommandozeile`, r3.rc === 1 && !r3.text.includes('::error title=injiziert') && r3.text.split('\n').filter(l => l.startsWith('::')).length === 1);
  }
  const ohneBeide = lauf({ ereignis: 'schedule' });
  const ohneEinmal = lauf({ ereignis: 'schedule', taeglich: true });
  const ohneDauer = lauf({ ereignis: 'schedule', frei: true });
  wahr('Hinweis nennt beide fehlenden Dateien getrennt', /GMC-SCHAUFENSTER-FREI\.txt fehlt/.test(ohneBeide.text) && /GMC-SCHAUFENSTER-TAEGLICH-FREI\.txt fehlt/.test(ohneBeide.text));
  wahr('Hinweis bei nur fehlender Einmalfreigabe ist korrekt', /GMC-SCHAUFENSTER-FREI\.txt fehlt/.test(ohneEinmal.text) && !/TAEGLICH-FREI\.txt fehlt/.test(ohneEinmal.text));
  wahr('Hinweis bei nur fehlender Dauerfreigabe ist korrekt', /TAEGLICH-FREI\.txt fehlt/.test(ohneDauer.text) && !/GMC-SCHAUFENSTER-FREI\.txt fehlt/.test(ohneDauer.text));
}
function schrittLauf(name, extra = {}) {
  const d = mkdtempSync(join(tmpdir(), 'gmcwf-schritt-'));
  try {
    const bin = join(d, 'bin'); mkdirSync(bin);
    writeFileSync(join(bin, 'node'), '#!/usr/bin/env bash\nprintf "%s\\n" "$FAKE_TEXT"\nexit "$FAKE_RC"\n', { mode: 0o755 });
    writeFileSync(join(bin, 'sleep'), '#!/usr/bin/env bash\nexit 0\n', { mode: 0o755 });
    writeFileSync(join(bin, 'timeout'), '#!/usr/bin/env bash\nprintf "%s\\n" "$1" >> "$FAKE_TIMEOUT_LOG"\nshift\nexec "$@"\n', { mode: 0o755 });
    const out = join(d, 'out'); writeFileSync(out, '');
    const script = schritt(name)?.replaceAll('/tmp/gmc_schaufenster_', d + '/gmc_schaufenster_');
    if (!script) return { rc: null, text: 'Schritt fehlt', out: '', timeout: '' };
    const r = spawnSync('bash', ['-eo', 'pipefail', '-c', script], {
      cwd: d, encoding: 'utf8', timeout: 5000,
      env: { PATH: bin + ':' + process.env.PATH, GITHUB_OUTPUT: out, FAKE_RC: '0', FAKE_TEXT: 'Attrappe', FAKE_TIMEOUT_LOG: join(d, 'timeout.txt'), LIVE: '0', LAUF_MODUS: 'abwaehlen', LAUF_MAX: 'alle', LAUF_RC: '0', ...extra },
    });
    const optional = n => { try { return readFileSync(join(d, n), 'utf8'); } catch { return ''; } };
    return { rc: r.status, text: (r.stdout || '') + (r.stderr || ''), out: optional('out'), timeout: optional('timeout.txt') };
  } finally { rmSync(d, { recursive: true, force: true }); }
}
{
  const name = 'Schaufenster (${{ steps.modus.outputs.modus }})';
  let r = schrittLauf(name, { FAKE_RC: '4', LIVE: '0' });
  wahr('Exit4 beim Lesen ist rot und nennt unbekannte Prüfung', r.rc === 4 && /nicht geprüft|unbekannt/.test(r.text), JSON.stringify(r));
  r = schrittLauf(name, { FAKE_RC: '4', LIVE: '1' });
  wahr('Exit4 beim Schreiben erhält Manifest-Pfad und warnt', r.rc === 0 && /::warning/.test(r.text) && r.out.includes('rc=4'));
  r = schrittLauf(name, { FAKE_RC: '124', LIVE: '1' });
  wahr('Eigenes Zeitlimit wird als Exit4 protokolliert', r.rc === 0 && r.out.includes('rc=4') && /Zeitlimit/.test(r.text) && r.timeout.trim() === '325m', JSON.stringify(r));
  r = schrittLauf(name, { FAKE_RC: '124', LIVE: '0' });
  wahr('Zeitlimit beim Lesen ist unbekannt und nicht grün', r.rc === 4 && r.out.includes('rc=4'));
  for (const rc of [0,1,2,3,5]) {
    r = schrittLauf(name, { FAKE_RC: String(rc), LIVE: '1' });
    wahr(`Lauf-Exit${rc} bleibt sichtbar`, r.rc === rc && r.out.includes(`rc=${rc}`));
  }
}
{
  const name = 'Nachprüfen (frisch lesen, nach 2 Minuten Abstand)';
  for (const c of [{LAUF_MODUS:'aufnehmen'},{LAUF_MODUS:'zuruecksetzen'},{LAUF_MAX:'50'},{LAUF_RC:'4'},{LAUF_RC:'3'}]) {
    const r = schrittLauf(name, { FAKE_RC: '5', ...c });
    wahr(`Nachprüfung Exit5 bei ${JSON.stringify(c)} ist erklärter Hinweis`, r.rc === 0 && /::notice/.test(r.text) && r.out.includes('rc=5'), JSON.stringify(r));
  }
  let r = schrittLauf(name, { FAKE_RC:'5' });
  wahr('Vollständige erfolgreiche Abwahl mit Resten bleibt rot', r.rc === 5 && r.out.includes('rc=5'));
  for (const rc of [2,3]) {
    r = schrittLauf(name, { FAKE_RC: String(rc), LAUF_MODUS:'aufnehmen', LAUF_MAX:'5', LAUF_RC:'4' });
    wahr(`Nachprüfung Exit${rc} bleibt trotz Teil-/Rücknahmelauf rot`, r.rc === rc);
  }
  r = schrittLauf(name, { FAKE_RC:'124' });
  wahr('Auch Nachprüfung ist begrenzt und nennt unbekannt statt Defekt', r.rc === 0 && r.out.includes('rc=4') && /::warning/.test(r.text) && r.timeout.trim() === '7m');
}
wahr('Shell in der Praxis ausdrücklich bash', /defaults:\s*\n\s+run:\s*\n\s+shell: bash/.test(WF));
wahr('Branchdaten kommen über env und Manifestziel ist Standardzweig', /QUELL_REF: \$\{\{ github\.ref \}\}/.test(WF) && /STANDARDZWEIG: \$\{\{ github\.event\.repository\.default_branch \}\}/.test(WF) && /ZIEL: \$\{\{ github\.event\.repository\.default_branch \}\}/.test(WF) && !/ZIEL: \$\{\{ github\.ref_name/.test(WF));
wahr('Nachprüfung auch nach Teilfehler Exit3', /steps\.lauf\.outputs\.rc == '3'/.test(WF));
for (const text of ['PLAN NICHT ERLAUBT','WARNUNG','ABWAEHLEN:','AUFNEHMEN:','Google trägt']) wahr(`Zusammenfassung enthält ${text}`, schritt('Zusammenfassung')?.includes(text));
wahr('Workflow-Kopf nennt Lauf abbrechen UND Datei löschen', /laufenden Lauf abbrechen UND Datei löschen/.test(WF));
const DOKU = readFileSync(fileURLToPath(new URL('../dropship/GMC-SCHAUFENSTER-2810.md', import.meta.url)), 'utf8');
wahr('Doku nennt Stopp und wartende Läufe vor Rücknahme', /laufenden Lauf abbrechen UND Datei löschen/.test(DOKU) && /wartet|wartenden/.test(DOKU));

console.log(`${ok} ok, ${fehl} Fehler`);
process.exit(fehl ? 1 : 0);
